var _markdown = "\n\n`sa` · 扩展 `CLEO+` · 需 CLEO + CLEO+\n\n写法见 [Lua](/docs/cleo/syntax) / [Redux](/docs/cleo/syntax-redux)。\n\n## 1D Perlin [#1d-perlin]\n\n<Opcode id=\"0E03\" name=\"PERLIN_NOISE\" member=\"Math.PerlinNoise\">\n  1D Perlin simplex 噪声。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0E03 PERLIN_NOISE\n      in: x\n      out: result\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local n = perlinNoise(t)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const result = Math.perlinNoise(x)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 缓动 [#缓动]\n\n<Opcode id=\"0E1F\" name=\"EASE\" member=\"Math.Ease\">\n  把 `k`（0–1）按 mode / way 做缓动，适合动画。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0E1F EASE\n      in: k, mode, way\n      out: result\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local e = ease(0.5, mode, way)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const result = Math.ease(k, mode, way)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 两点夹角 [#两点夹角]\n\n<Opcode id=\"0E27\" name=\"GET_ANGLE_FROM_TWO_COORDS\" member=\"Math.GetAngleFromTwoCoords\">\n  两点平面角。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0E27 GET_ANGLE_FROM_TWO_COORDS\n      in: x1, y1, x2, y2\n      out: angle\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local a = getAngleFromTwoCoords(x1, y1, x2, y2)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const angle = Math.getAngleFromTwoCoords(x1, y1, x2, y2)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## Perlin fBm [#perlin-fbm]\n\n<Opcode id=\"0E29\" name=\"PERLIN_NOISE_FRACTAL\" member=\"Math.PerlinNoiseFractal\">\n  1D Perlin 的 fBm 叠加。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0E29 PERLIN_NOISE_FRACTAL\n      in: x, octaves, frequency, amplitude, lacunarity, persistence\n      out: result\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local n = perlinNoiseFractal(t, 4, 1.0, 1.0, 2.0, 0.5)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const result = Math.perlinNoiseFractal(x, octaves, frequency, amplitude, lacunarity, persistence)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 百分比随机 [#百分比随机]\n\n<Opcode id=\"0E4D\" name=\"RANDOM_PERCENT\" member=\"Math.RandomPercent\">\n  约 `percent`% 概率为真。用在 `if` 里。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0E4D RANDOM_PERCENT\n      in: percent\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      if randomPercent(25) then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      if (Math.randomPercent(percent)) {\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 带种子整数随机 [#带种子整数随机]\n\n<Opcode id=\"0EBC\" name=\"GENERATE_RANDOM_INT_IN_RANGE_WITH_SEED\" member=\"Math.GenerateRandomIntInRangeWithSeed\">\n  `[min, max)`。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0EBC GENERATE_RANDOM_INT_IN_RANGE_WITH_SEED\n      in: seed, min, max\n      out: randomInteger\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local n = generateRandomIntInRangeWithSeed(seed, 0, 100)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const randomInteger = Math.generateRandomIntInRangeWithSeed(seed, min, max)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 带种子浮点随机 [#带种子浮点随机]\n\n<Opcode id=\"0EBD\" name=\"GENERATE_RANDOM_FLOAT_IN_RANGE_WITH_SEED\" member=\"Math.GenerateRandomFloatInRangeWithSeed\">\n  `[min, max)`。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0EBD GENERATE_RANDOM_FLOAT_IN_RANGE_WITH_SEED\n      in: seed, min, max\n      out: randomFloat\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local f = generateRandomFloatInRangeWithSeed(seed, 0.0, 1.0)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const randomFloat = Math.generateRandomFloatInRangeWithSeed(seed, min, max)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 2D Perlin fBm [#2d-perlin-fbm]\n\n<Opcode id=\"0EF1\" name=\"PERLIN_NOISE_FRACTAL_2D\" member=\"Math.PerlinNoiseFractal2D\">\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0EF1 PERLIN_NOISE_FRACTAL_2D\n      in: x, y, octaves, frequency, amplitude, lacunarity, persistence\n      out: result\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local n = perlinNoiseFractal2D(x, y, 4, 1.0, 1.0, 2.0, 0.5)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const result = Math.perlinNoiseFractal2D(x, y, octaves, frequency, amplitude, lacunarity, persistence)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 3D Perlin fBm [#3d-perlin-fbm]\n\n<Opcode id=\"0EF2\" name=\"PERLIN_NOISE_FRACTAL_3D\" member=\"Math.PerlinNoiseFractal3D\">\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0EF2 PERLIN_NOISE_FRACTAL_3D\n      in: x, y, z, octaves, frequency, amplitude, lacunarity, persistence\n      out: result\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local n = perlinNoiseFractal3D(x, y, z, 4, 1.0, 1.0, 2.0, 0.5)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const result = Math.perlinNoiseFractal3D(x, y, z, octaves, frequency, amplitude, lacunarity, persistence)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 线性插值 [#线性插值]\n\n<Opcode id=\"0EF3\" name=\"LERP\">\n  `a + (b-a)*t`。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0EF3 LERP\n      in: a, b, t\n      out: result\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local v = lerp(0.0, 1.0, 0.5)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const result = native(\"LERP\", a, b, t)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 浮点夹值 [#浮点夹值]\n\n<Opcode id=\"0EF4\" name=\"CLAMP_FLOAT\" member=\"Math.ClampFloat\">\n  浮点夹到 `[min, max]`。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0EF4 CLAMP_FLOAT\n      in: float, min, max\n      out: clamped\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local v = clampFloat(x, 0.0, 1.0)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const clamped = Math.clampFloat(float, min, max)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 整数夹值 [#整数夹值]\n\n<Opcode id=\"0EF7\" name=\"CLAMP_INT\" member=\"Math.ClampInt\">\n  整数夹到 `[min, max]`。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0EF7 CLAMP_INT\n      in: integer, min, max\n      out: clamped\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local v = clampInt(n, 0, 100)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const clamped = Math.clampInt(integer, min, max)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n";
